                throw BizException.conflict("采收批已冻结，不得进入加工: " + harvestBatchId);
            }
            if (batch.status() != BatchStatus.RELEASED) {
                throw BizException.conflict("采收批未放行，不得进入加工: " + harvestBatchId);
            }
        }
