                        try {
                            recallService.withdrawRecall(recall.id(), new WithdrawRecallRequest(
                                    "REQ-CC-WD-" + (i + 1), 1L, "QC-A", "QC-B",
                                    "WCRED-A-" + i, "WCRED-B-" + i));
                            return "OK";
                        } catch (BizException e) {
                            return "BIZ:" + e.status().value();
                        }
                    }))
